// DoorLoop occupancy → Properties sheet.
//
// Rule: a unit is occupied if its id appears in the units[] array of any lease
// with calculatedStatus == "ACTIVE". Each sheet row maps to exactly one DoorLoop
// UNIT id (stored in doorloop_property_id by scripts/doorloop-match.mjs), so a
// row's status is just that unit's occupancy — no roll-up needed.

const unitsResp = $('Fetch Units').first().json;
const leasesResp = $('Fetch Active Leases').first().json;
const rows = $('Read Properties').all().map((i) => i.json);

const units = unitsResp.data ?? [];
const leases = leasesResp.data ?? [];

// Guard: page_size is 1000 and the portfolio is ~70 units, so a truncated page
// means the portfolio outgrew a single page. Fail loudly rather than silently
// marking every unpaged unit vacant.
if ((unitsResp.total ?? units.length) > units.length) {
  throw new Error(`Units response truncated: total=${unitsResp.total} but only ${units.length} returned. Add pagination.`);
}
if ((leasesResp.total ?? leases.length) > leases.length) {
  throw new Error(`Leases response truncated: total=${leasesResp.total} but only ${leases.length} returned. Add pagination.`);
}
if (units.length === 0) {
  throw new Error('DoorLoop returned zero units — refusing to mark the whole portfolio vacant.');
}

// Sheets returns numbers as numbers; ids must be compared as strings.
const occupiedUnitIds = new Set();
for (const lease of leases) {
  if (String(lease.calculatedStatus ?? '').toUpperCase() !== 'ACTIVE') continue;
  for (const unitId of lease.units ?? []) occupiedUnitIds.add(String(unitId));
}

const knownUnitIds = new Set(units.map((u) => String(u.id)));

const now = new Date().toISOString();
const out = [];
const stale = [];
let overridden = 0;
let unmapped = 0;

for (const row of rows) {
  const propertyKey = String(row.property_key ?? '').trim();
  const dlUnitId = String(row.doorloop_property_id ?? '').trim();

  if (!propertyKey) continue;

  // No DoorLoop counterpart — status stays whatever a human set. Never touched.
  if (!dlUnitId) {
    unmapped += 1;
    continue;
  }

  // Mapping points at a unit DoorLoop no longer returns (deleted/archived).
  // Skip rather than guess: writing 'vacant' here would be a silent data loss.
  if (!knownUnitIds.has(dlUnitId)) {
    stale.push(`${propertyKey} → ${dlUnitId}`);
    continue;
  }

  const doorloopStatus = occupiedUnitIds.has(dlUnitId) ? 'occupied' : 'vacant';
  const override = String(row.status_override ?? '').trim().toLowerCase();
  if (override) overridden += 1;

  out.push({
    json: {
      property_key: propertyKey,
      // Always written: what DoorLoop actually reports, so the dashboard can show
      // the real value alongside an override.
      doorloop_status: doorloopStatus,
      doorloop_synced_at: now,
      // An active admin override wins. We rewrite it to its own value rather than
      // omitting the field, so the Sheets node can't blank the cell.
      status: override || doorloopStatus,
    },
  });
}

console.log(`[doorloop-sync] units=${units.length} activeLeases=${leases.length} occupiedUnits=${occupiedUnitIds.size}`);
console.log(`[doorloop-sync] writing=${out.length} overridden=${overridden} unmapped=${unmapped} stale=${stale.length}`);
if (stale.length) {
  console.log(`[doorloop-sync] STALE MAPPINGS (doorloop_property_id not found in DoorLoop): ${stale.join(', ')}`);
}

if (out.length === 0) {
  throw new Error('No rows to write — every row is unmapped or stale. Check doorloop_property_id in the Properties sheet.');
}

return out;
